import React, { useState } from 'react';
import { chatWithBot } from './api/apiClient';

const Chatbot = ({ applicantId, token }) => {
  const [question, setQuestion] = useState('');
  const [answer, setAnswer] = useState('');
  const [loading, setLoading] = useState(false);

  const handleAsk = async (e) => {
    e.preventDefault();
    setLoading(true);
    setAnswer('');
    try {
      const res = await chatWithBot(question, applicantId, token);
      setAnswer(res.data.answer);
    } catch {
      setAnswer('Error getting answer.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h2>Chat</h2>
      <form onSubmit={handleAsk} className="toolbar">
        <input className="input" type="text" value={question} onChange={e => setQuestion(e.target.value)} placeholder="Ask a question…" required />
        <button className="btn" type="submit" disabled={loading}>{loading ? 'Asking…' : 'Ask'}</button>
      </form>
      {answer && <div className="card"><b>Answer:</b> <span className="muted">{answer}</span></div>}
    </div>
  );
};

export default Chatbot;
